def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    mean_rem = np.mean(remaining[valid])
    variance_penalty = np.where(valid, -np.cos((remaining - mean_rem) / (np.std(remaining[valid]) + 1e-8)), 0.0)
    efficiency = np.where(valid, 1.0 / (1.0 + np.exp(remaining)), 0.0)
    return np.where(valid, efficiency + 0.2 * variance_penalty, -np.inf)

